Create Customer.code:
// Create a customer.
create(
  // 1) Doctype.
  'Customer',
  // 2) Document fields.
  {
    customer_name: $.data.organisationName,
    customer_type: 'Company',
    customer_group: 'Non Profit',
    territory: 'Kenya',
  }
);

Create Material Request.code:
// Raise a material request for low stock at a facility.
create('Material Request', {
  material_request_type: 'Purchase',
  transaction_date: $.data.reportDate,
  schedule_date: $.data.neededBy,
  items: [
    {
      item_code: $.data.itemCode,
      qty: $.data.quantityNeeded,
      // Warehouse to deliver to.
      warehouse: $.data.warehouse,
    },
  ],
});

Create Stock Entry.code:
// Transfer stock from a central store to a facility.
create('Stock Entry', {
  stock_entry_type: 'Material Transfer',
  items: [
    {
      item_code: 'ORS-SACHET',
      qty: 500,
      s_warehouse: 'Central Medical Store - CMS',
      t_warehouse: 'Kilifi Clinic - CMS',
    },
  ],
});

Create Item.code:
// Add an item to the item master.
create('Item', {
  item_code: $.data.itemCode,
  item_name: 'Amoxicillin 250mg Dispersible Tablets',
  item_group: 'Medicines',
  stock_uom: 'Nos',
});

Update Document.code:
// Update an existing document.
update(
  // 1) Doctype.
  'Customer',
  // 2) Document name/ID.
  $.data.customerId,
  // 3) Fields to change.
  {
    mobile_no: $.data.phone,
    email_id: $.data.email,
  }
);

Delete Document.code:
// Delete a draft document.
deleteRecord(
  // 1) Doctype.
  'Material Request',
  // 2) Document name/ID.
  $.data.materialRequestId
);

Read Document.code:
// Fetch one document by name.
read(
  // 1) Doctype.
  'Item',
  // 2) Document name/ID.
  $.data.itemCode
);

List Documents with Filters.code:
// List submitted purchase orders for a supplier.
getList('Purchase Order', {
  fields: ['name', 'supplier', 'transaction_date', 'grand_total', 'status'],
  filters: { supplier: $.data.supplier, docstatus: 1 },
  orderBy: { field: 'transaction_date', order: 'desc' },
  limit: 100,
});

Count Documents.code:
// Count open material requests.
getCount(
  // 1) Doctype.
  'Material Request',
  // 2) Filters.
  { status: 'Pending' }
);
